'use strict';
const novels=window.NOVELS||[];
const main=document.querySelector('#main');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let saved=read('novelnest.saved',[]);if(!Array.isArray(saved))saved=[];saved=saved.filter(id=>novels.some(n=>n.id===id));
let progress=read('novelnest.progress',{});if(!progress||typeof progress!=='object'||Array.isArray(progress))progress={};
let preferences=read('novelnest.preferences',{});if(!preferences||typeof preferences!=='object')preferences={};
let storageWarning=false;
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{if(!storageWarning){toast('Storage is unavailable. Changes will last for this visit.');storageWarning=true}}}
function toast(text){const el=document.querySelector('#toast');if(!el)return;el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200)}
function applySettings(){document.body.dataset.theme=['night','sepia'].includes(preferences.theme)?preferences.theme:'light';document.documentElement.style.setProperty('--reader-size',`${Math.min(28,Math.max(16,Number(preferences.size)||20))}px`)}
function toggleSave(id){if(!novels.some(n=>n.id===id))return;const exists=saved.includes(id);saved=exists?saved.filter(x=>x!==id):[...saved,id];persist('novelnest.saved',saved);const count=document.querySelector('#library-count');if(count)count.textContent=saved.length;document.querySelectorAll('[data-save]').forEach(b=>{if(b.dataset.save===id){b.textContent=saved.includes(id)?'♥ Saved in library':'♡ Save to library';b.setAttribute('aria-pressed',String(saved.includes(id)))}});toast(exists?'Removed from your library':'Saved to your library on this device')}
const bookUrl=n=>`#/novel/${n.id}`;
const chapterUrl=(n,i)=>`#/read/${n.id}/${i+1}`;
const image=n=>`<img class="cover" src="${esc(n.cover)}" alt="${esc(n.title)} cover" loading="lazy" width="200" height="300">`;
const genres=[...new Set(novels.flatMap(n=>n.tags||[]))].sort();
function searchForm(value=''){return `<form class="search-form" role="search"><span aria-hidden="true">⌕</span><input name="q" aria-label="Search novels by title or author" placeholder="Search titles, authors, genres…" value="${esc(value)}"><button aria-label="Search" type="submit">Search</button></form>`}
function chips(selected='All'){return `<div class="chips" aria-label="Filter by genre">${['All',...genres].map(g=>`<a class="chip ${selected===g?'selected':''}" ${selected===g?'aria-current="true"':''} href="#/browse${g==='All'?'':'?genre='+encodeURIComponent(g)}">${esc(g)}</a>`).join('')}</div>`}
function card(n){return `<a class="book-card" href="${bookUrl(n)}">${image(n)}<div><span class="tag">${esc(n.genre)}</span><h3>${esc(n.title)}</h3><p>${esc(n.author)}</p><p>${n.chapters.length} chapters · ${esc(n.status)}</p><span class="meta">Licensed novel</span></div></a>`}
function lastRead(n){const p=progress[n.id];return p&&Number.isInteger(p.chapter)&&p.chapter>=0&&p.chapter<n.chapters.length?p:null}
function latestRows(limit=12){return novels.flatMap(n=>n.chapters.map((c,i)=>({n,c,i}))).sort((a,b)=>b.n.updated.localeCompare(a.n.updated)||b.i-a.i).slice(0,limit).map(({n,c,i})=>`<a class="chapter-row" href="${chapterUrl(n,i)}">${image(n)}<div><strong>${esc(n.title)}</strong><p>Chapter ${i+1}: ${esc(c.title)}</p></div><time datetime="${n.updated}">${new Date(n.updated+'T00:00:00Z').toLocaleDateString('en',{month:'short',day:'numeric',timeZone:'UTC'})}</time></a>`).join('')}
function continueBox(){const recent=novels.filter(n=>lastRead(n)).sort((a,b)=>(lastRead(b).at||0)-(lastRead(a).at||0))[0];return recent?`<section class="continue-box"><div><span class="eyebrow">Continue reading</span><p><strong>${esc(recent.title)}</strong> · Chapter ${lastRead(recent).chapter+1}</p></div><a class="button" href="${chapterUrl(recent,lastRead(recent).chapter)}">Continue</a></section>`:''}
function home(){if(!novels.length)return missing();const n=novels[0],p=lastRead(n);return `<section class="intro"><div><span class="eyebrow">Make time for a good story</span><h1>Find your next chapter.</h1><p class="muted">Read authorized novels chapter by chapter on NovelNest.</p></div>${searchForm()}</section>${chips()}${continueBox()}<section class="featured" aria-label="Featured novel"><article class="spotlight">${image(n)}<div><span class="eyebrow">Featured licensed novel</span><h2>${esc(n.title)}</h2><div class="meta">${esc(n.genre)} · ${n.chapters.length} chapters · ${esc(n.status)}</div><p>${esc(n.synopsis)}</p><a class="button light" href="${p?chapterUrl(n,p.chapter):bookUrl(n)}">${p?'Continue reading':'View novel'}</a></div></article></section><section><div class="section-head"><h2>Available now</h2><a class="text-link" href="#/browse">Browse</a></div><div class="catalog-grid">${novels.map(card).join('')}</div></section><div class="lower-grid"><section><div class="section-head"><h2>Latest chapters</h2><a class="text-link" href="#/latest">View all</a></div><div class="chapter-list">${latestRows(6)}</div></section><section><div class="section-head"><h2>Explore by genre</h2></div><div class="genre-box">${genres.map(g=>`<a class="genre-row" href="#/browse?genre=${encodeURIComponent(g)}">${esc(g)}<span>${novels.filter(n=>n.tags.includes(g)).length} ${novels.filter(n=>n.tags.includes(g)).length===1?'novel':'novels'}</span></a>`).join('')}</div></section></div>`}
function browse(params){const q=params.get('q')||'',genre=params.get('genre')||'All',status=params.get('status')||'All',sort=params.get('sort')||'latest';let results=novels.filter(n=>(genre==='All'||n.tags.includes(genre))&&(status==='All'||n.status===status)&&`${n.title} ${n.author} ${n.tags.join(' ')}`.toLowerCase().includes(q.toLowerCase()));results.sort(sort==='title'?(a,b)=>a.title.localeCompare(b.title):(a,b)=>b.updated.localeCompare(a.updated));return `<section class="intro"><div><span class="eyebrow">Your next escape</span><h1>Browse novels</h1><p class="muted">Authorized novels available to read directly on NovelNest.</p></div>${searchForm(q)}</section>${chips(genre)}<div class="toolbar"><span class="muted">${results.length} ${results.length===1?'novel':'novels'}${q?` matching “${esc(q)}”`:''}</span><div><label for="status" class="muted">Status </label><select id="status" data-filter="status"><option ${status==='All'?'selected':''}>All</option><option ${status==='Completed'?'selected':''}>Completed</option><option ${status==='Ongoing'?'selected':''}>Ongoing</option></select> <label for="sort" class="muted">Sort </label><select id="sort" data-filter="sort"><option value="latest" ${sort==='latest'?'selected':''}>Latest added</option><option value="title" ${sort==='title'?'selected':''}>Title A–Z</option></select></div></div>${results.length?`<div class="catalog-grid">${results.map(card).join('')}</div>`:`<div class="empty"><h2>No novels found</h2><p>Try a different title or genre, or clear your filters.</p><a class="button" href="#/browse">Clear filters</a></div>`}`}
function detail(id){const n=novels.find(x=>x.id===id);if(!n)return missing();const p=lastRead(n);const latest=n.chapters.map((c,i)=>({c,i})).slice(-6).reverse();return `<div class="breadcrumb"><a href="#/browse">Browse novels</a><span>/</span><span>${esc(n.title)}</span></div><article class="detail">${image(n)}<div class="book-info"><span class="eyebrow">${n.tags.map(esc).join(' / ')}</span><h1>${esc(n.title)}</h1><p class="muted">by ${esc(n.author)}</p><span class="status-pill">${esc(n.status)}</span><p class="meta">${n.chapters.length} chapters · English · Licensed edition</p></div><div class="description" style="grid-column:1/-1"><h2>About the story</h2><p>${esc(n.synopsis)}</p><p class="meta">${esc(n.license.type)} · ${esc(n.license.note)}</p></div><div class="actions" style="grid-column:1/-1"><a class="button" href="${chapterUrl(n,p?p.chapter:0)}">${p?'Continue reading':'Start reading'}</a><button class="button outline" data-save="${n.id}" aria-pressed="${saved.includes(n.id)}">${saved.includes(n.id)?'♥ Saved in library':'♡ Save to library'}</button></div></article><section><div class="section-head"><h2>Latest chapters</h2><span class="meta">Newest first</span></div><div class="toc">${latest.map(({c,i})=>`<a href="${chapterUrl(n,i)}"><span>${String(i+1).padStart(2,'0')}</span>${esc(c.title)}</a>`).join('')}</div></section><section><div class="section-head"><h2>All chapters <span class="muted">(${n.chapters.length})</span></h2><span class="meta">Chapter 1 to ${n.chapters.length}</span></div><div class="toc">${n.chapters.map((c,i)=>`<a href="${chapterUrl(n,i)}"><span>${String(i+1).padStart(2,'0')}</span>${esc(c.title)} ${p?.chapter===i?'<span>Last opened</span>':''}</a>`).join('')}</div></section>`}
function reader(id,number){const n=novels.find(x=>x.id===id),i=Number(number)-1;if(!n||!Number.isInteger(i)||i<0||i>=n.chapters.length)return missing();const c=n.chapters[i];progress[n.id]={chapter:i,at:Date.now()};persist('novelnest.progress',progress);return `<div class="reader-wrap"><div class="breadcrumb"><a href="${bookUrl(n)}">${esc(n.title)}</a><span>/ Chapter ${i+1}</span></div><div class="reader-tools"><div><label for="reader-theme">Appearance</label><select id="reader-theme"><option value="light" ${preferences.theme==='light'||!preferences.theme?'selected':''}>Light</option><option value="sepia" ${preferences.theme==='sepia'?'selected':''}>Sepia</option><option value="night" ${preferences.theme==='night'?'selected':''}>Night</option></select></div><div><button data-font="-2" aria-label="Decrease text size">A−</button><span id="font-size" class="meta">${preferences.size||20}px</span><button data-font="2" aria-label="Increase text size">A+</button></div><a class="text-link" href="${bookUrl(n)}">Chapters</a></div><article><div class="reader-heading"><span class="eyebrow">Chapter ${i+1} of ${n.chapters.length}</span><h1>${esc(c.title)}</h1><span class="meta">${esc(n.title)} · Licensed edition</span></div><div class="prose">${c.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</div></article><div class="chapter-nav">${i>0?`<a class="button outline" href="${chapterUrl(n,i-1)}">Previous chapter</a>`:'<button class="button outline" disabled>Previous chapter</button>'}${i<n.chapters.length-1?`<a class="button" href="${chapterUrl(n,i+1)}">Next chapter</a>`:`<a class="button" href="${bookUrl(n)}">Back to novel</a>`}</div><div class="end-note">${i===n.chapters.length-1?'You reached the latest available chapter.':'Your last opened chapter is saved on this device.'}</div></div>`}
function library(){const books=novels.filter(n=>saved.includes(n.id));return `<section class="intro"><div><span class="eyebrow">A shelf of your own</span><h1>My library</h1><p class="muted">Saved novels and reading progress on this device.</p></div></section>${continueBox()}${books.length?`<div class="catalog-grid">${books.map(card).join('')}</div>`:`<div class="empty"><h2>Your library is empty.</h2><p>Open a novel and select “Save to library” to keep it on your shelf.</p><a class="button" href="#/browse">Find a novel</a></div>`}`}
function missing(){return `<div class="empty"><h1>Page not found</h1><p>This novel or chapter is not available.</p><a class="button" href="#/browse">Browse novels</a></div>`}
function about(){return `<article class="about"><span class="eyebrow">A home for stories</span><h1>About NovelNest</h1><p>NovelNest is a place to read authorized novels chapter by chapter. Browse the catalog, save a novel to your library, and choose the reading appearance that feels comfortable.</p><h2>Our collection</h2><p>NovelNest hosts full chapters only for titles the site owner is authorized to publish. Got a Gallery in the Wild is currently available as a licensed on-site edition.</p><h2>Your reading data</h2><p>Bookmarks, reading preferences, and your last opened chapter are stored in your browser on this device. There is no account or cross-device sync. Clearing your browser data removes those saved settings.</p></article>`}
function route(){let raw=location.hash.slice(1)||'/';let [path,query='']=raw.split('?');const parts=path.split('/').filter(Boolean),params=new URLSearchParams(query);applySettings();const count=document.querySelector('#library-count');if(count)count.textContent=saved.length;document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===(parts[0]||'home');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});let html,title='Find your next chapter';switch(parts[0]){case undefined:html=home();break;case 'browse':html=browse(params);title='Browse novels';break;case 'latest':html=`<section class="intro"><div><span class="eyebrow">Fresh from the shelf</span><h1>Latest chapters</h1><p class="muted">Newest available chapters first.</p></div></section><div class="chapter-list">${latestRows(30)}</div>`;title='Latest chapters';break;case 'novel':html=detail(parts[1]);title=novels.find(n=>n.id===parts[1])?.title||'Not found';break;case 'read':html=reader(parts[1],parts[2]);title=`${novels.find(n=>n.id===parts[1])?.title||'Not found'} · Chapter ${parts[2]}`;break;case 'library':html=library();title='My library';break;case 'about':html=about();title='About & content';break;default:html=missing();title='Not found'}main.innerHTML=html;document.title=`${title} — NovelNest`;window.scrollTo(0,0)}
main.addEventListener('submit',e=>{if(e.target.matches('.search-form')){e.preventDefault();location.hash='/browse?q='+encodeURIComponent(new FormData(e.target).get('q').trim())}});
main.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save)toggleSave(save.dataset.save);const font=e.target.closest('[data-font]');if(font){preferences.size=Math.min(28,Math.max(16,(Number(preferences.size)||20)+Number(font.dataset.font)));persist('novelnest.preferences',preferences);applySettings();const size=document.querySelector('#font-size');if(size)size.textContent=preferences.size+'px'}});
main.addEventListener('change',e=>{if(e.target.id==='reader-theme'){preferences.theme=e.target.value;persist('novelnest.preferences',preferences);applySettings()}if(e.target.dataset.filter){const p=new URLSearchParams(location.hash.split('?')[1]||'');p.set(e.target.dataset.filter,e.target.value);location.hash='/browse?'+p.toString()}});
window.addEventListener('hashchange',()=>{route();main.focus({preventScroll:true})});const year=document.querySelector('#year');if(year)year.textContent=new Date().getFullYear();route();
